-- Phase 2d: Diagnostic (org-wide) question bank.
-- Separate from assessment_questions (per-asset). Scoring engine keeps stable question_keys;
-- Control Centre edits prompts/options. Multi (q1_2) + uncertainty flags live in options jsonb.

create table if not exists public.diagnostic_sections (
  section_key text primary key,
  title text not null,
  description text null,
  display_order integer not null default 0,
  is_active boolean not null default true,
  updated_at timestamptz not null default now()
);

create table if not exists public.diagnostic_questions (
  id uuid primary key default gen_random_uuid(),
  section_key text not null references public.diagnostic_sections(section_key) on delete cascade,
  question_key text not null unique,
  prompt text not null,
  hint text null,
  question_kind text not null default 'single' check (question_kind in ('single', 'multi')),
  is_required boolean not null default true,
  display_order integer not null default 0,
  is_active boolean not null default true,
  options jsonb not null default '[]'::jsonb,
  updated_at timestamptz not null default now(),
  constraint diagnostic_questions_options_is_array check (jsonb_typeof(options) = 'array')
);

create index if not exists diagnostic_questions_section_order_idx
  on public.diagnostic_questions (section_key, display_order)
  where is_active;

comment on table public.diagnostic_sections is
  'Org-wide diagnostic domains (lead funnel). Not the per-asset assessment engine.';
comment on table public.diagnostic_questions is
  'Diagnostic prompts + options. question_key feeds scoring, priority flags, and high-risk additions.';

alter table public.diagnostic_sections enable row level security;
alter table public.diagnostic_questions enable row level security;

drop policy if exists dqs_select on public.diagnostic_sections;
create policy dqs_select on public.diagnostic_sections for select to anon, authenticated using (true);
drop policy if exists dqs_mla_admin_write on public.diagnostic_sections;
create policy dqs_mla_admin_write on public.diagnostic_sections for all to authenticated
  using (public.is_mla_admin()) with check (public.is_mla_admin());

drop policy if exists dqq_select on public.diagnostic_questions;
create policy dqq_select on public.diagnostic_questions for select to anon, authenticated using (true);
drop policy if exists dqq_mla_admin_write on public.diagnostic_questions;
create policy dqq_mla_admin_write on public.diagnostic_questions for all to authenticated
  using (public.is_mla_admin()) with check (public.is_mla_admin());

grant select on public.diagnostic_sections to anon, authenticated;
grant select, insert, update, delete on public.diagnostic_sections to authenticated;
grant select on public.diagnostic_questions to anon, authenticated;
grant select, insert, update, delete on public.diagnostic_questions to authenticated;

do $do$
declare
  seed jsonb := $json$[{"section_key":"s1","title":"AI Inventory & Classification","description":"Identifying AI systems in scope and establishing potential regulatory exposure.","display_order":10,"questions":[{"question_key":"q1_1","prompt":"Does your organisation maintain an up-to-date inventory of all AI systems currently in use, including third-party AI tools integrated into business processes?","hint":null,"question_kind":"single","display_order":10,"options":[{"label":"Yes: fully maintained and reviewed at least annually","score":3,"uncertainty":false},{"label":"Partially: some systems documented but not comprehensively","score":1,"uncertainty":false},{"label":"No formal inventory exists","score":0,"uncertainty":false},{"label":"Don't know","score":0,"uncertainty":true}],"is_required":true},{"question_key":"q1_2","prompt":"Which of the following categories apply to your AI systems?","hint":"These categories align with EU AI Act Annex III high-risk classifications. Select all that apply. Selections affect your exposure score.","question_kind":"multi","display_order":20,"options":[{"label":"Automated decision support affecting individuals","value":"auto"},{"label":"Customer profiling or segmentation","value":"profile"},{"label":"Customer eligibility or credit scoring","value":"credit"},{"label":"HR or recruitment support","value":"hr"},{"label":"Biometric or identity verification","value":"bio"},{"label":"Health or safety related outputs","value":"health"},{"label":"None of the above: AI is used only for internal operational tasks","value":"none"}],"is_required":false},{"question_key":"q1_3","prompt":"Have your AI systems been formally assessed against legal and regulatory requirements specific to your sector?","hint":null,"question_kind":"single","display_order":30,"options":[{"label":"Yes: documented assessment, reviewed within the last 12 months","score":3,"uncertainty":false},{"label":"Yes: informally reviewed but not documented","score":1,"uncertainty":false},{"label":"No: not yet assessed","score":0,"uncertainty":false},{"label":"Unsure whether this is required for our AI use","score":0,"uncertainty":true}],"is_required":true},{"question_key":"q1_4","prompt":"Does your organisation have a documented process for onboarding new AI systems, including a risk assessment before deployment?","hint":null,"question_kind":"single","display_order":40,"options":[{"label":"Yes: formal onboarding process with documented risk gate","score":3,"uncertainty":false},{"label":"Partially: some review occurs but not consistently applied","score":2,"uncertainty":false},{"label":"No: AI systems are adopted without structured review","score":0,"uncertainty":false},{"label":"Not applicable: we have not adopted any new AI systems recently","score":1,"uncertainty":false}],"is_required":true}]},{"section_key":"s2","title":"Governance, Leadership & Accountability","description":"Assessing the maturity of internal ownership and oversight structures.","display_order":20,"questions":[{"question_key":"q2_1","prompt":"Is there a formally appointed individual or function responsible for AI governance, with defined, documented responsibilities and a clear reporting line?","hint":null,"question_kind":"single","display_order":10,"options":[{"label":"Yes: named individual or function with documented scope and board-level reporting","score":3,"uncertainty":false},{"label":"Yes: but informally arranged with no documented mandate","score":1,"uncertainty":false},{"label":"No: responsibility is unclear or distributed without accountability","score":0,"uncertainty":false}],"is_required":true},{"question_key":"q2_2","prompt":"Are AI systems formally classified by risk level within your organisation?","hint":null,"question_kind":"single","display_order":20,"options":[{"label":"Yes: with a written classification framework applied consistently","score":3,"uncertainty":false},{"label":"Partially: some classification exists but inconsistently applied","score":2,"uncertainty":false},{"label":"No formal classification in place","score":0,"uncertainty":false},{"label":"Not yet required at our current stage of AI adoption","score":1,"uncertainty":false}],"is_required":true},{"question_key":"q2_3","prompt":"Does executive leadership receive regular, documented reporting on AI risk, performance, and governance status?","hint":null,"question_kind":"single","display_order":30,"options":[{"label":"Yes: at least quarterly, with documented minutes or records","score":3,"uncertainty":false},{"label":"Yes: occasionally, but not on a regular schedule","score":1,"uncertainty":false},{"label":"No: AI risk is not reported to executive or board level","score":0,"uncertainty":false}],"is_required":true},{"question_key":"q2_4","prompt":"Are documented policies in place governing the acceptable and prohibited use of AI systems across your organisation?","hint":null,"question_kind":"single","display_order":40,"options":[{"label":"Yes: comprehensive AI use policy, reviewed within 12 months","score":3,"uncertainty":false},{"label":"Partially: some guidance exists but not a comprehensive policy","score":1,"uncertainty":false},{"label":"No policies in place","score":0,"uncertainty":false}],"is_required":true},{"question_key":"q2_5","prompt":"Are roles and responsibilities for AI oversight explicitly defined across risk, compliance, legal, and technical functions?","hint":null,"question_kind":"single","display_order":50,"options":[{"label":"Yes: clearly defined in writing with named role holders","score":3,"uncertainty":false},{"label":"Partially: some functions have defined roles but others do not","score":2,"uncertainty":false},{"label":"No: roles are assumed rather than assigned","score":0,"uncertainty":false}],"is_required":true},{"question_key":"q2_6","prompt":"Is AI awareness or literacy training provided to staff who interact with, rely upon, or are affected by AI-generated outputs?","hint":null,"question_kind":"single","display_order":60,"options":[{"label":"Yes: mandatory training with completion records maintained","score":3,"uncertainty":false},{"label":"Yes: available but voluntary, no completion tracking","score":2,"uncertainty":false},{"label":"Planned but not yet implemented","score":1,"uncertainty":false},{"label":"No training in place","score":0,"uncertainty":false}],"is_required":true}]},{"section_key":"s3","title":"Data Quality, Lineage & Management","description":"Confirming that your AI systems are supported by clear, auditable data practices.","display_order":30,"questions":[{"question_key":"q3_1","prompt":"Is the origin and source of data used by AI systems documented and accessible, including how it is collected, processed, and updated?","hint":"i.e. where data comes from, how it is collected and processed","question_kind":"single","display_order":10,"options":[{"label":"Fully documented and accessible to relevant staff","score":3,"uncertainty":false},{"label":"Partially documented: some sources recorded but not comprehensively","score":1,"uncertainty":false},{"label":"Not documented","score":0,"uncertainty":false}],"is_required":true},{"question_key":"q3_2","prompt":"Do you maintain records of data lineage for core AI systems?","hint":"Sources, transformations applied, and version history","question_kind":"single","display_order":20,"options":[{"label":"Yes: comprehensive lineage records maintained and version-controlled","score":3,"uncertainty":false},{"label":"Partially: some lineage tracked but not consistently","score":2,"uncertainty":false},{"label":"Limited records: ad-hoc rather than systematic","score":1,"uncertainty":false},{"label":"No lineage records maintained","score":0,"uncertainty":false}],"is_required":true},{"question_key":"q3_3","prompt":"Do you perform regular data quality assessments for inputs feeding AI decisions, covering completeness, accuracy, and representativeness?","hint":null,"question_kind":"single","display_order":30,"options":[{"label":"Yes: scheduled assessments with documented results","score":3,"uncertainty":false},{"label":"Yes: but ad-hoc and undocumented","score":1,"uncertainty":false},{"label":"No assessments performed","score":0,"uncertainty":false}],"is_required":true},{"question_key":"q3_4","prompt":"Is there a documented process for identifying, escalating, and resolving data quality issues that affect AI system inputs or outputs?","hint":null,"question_kind":"single","display_order":40,"options":[{"label":"Yes: formal documented process with escalation path","score":3,"uncertainty":false},{"label":"Yes: informal process exists but not documented","score":1,"uncertainty":false},{"label":"No process exists","score":0,"uncertainty":false}],"is_required":true}]},{"section_key":"s4","title":"Human Oversight & Decision Controls","description":"Evaluating how human judgement integrates with AI-driven decisions.","display_order":40,"questions":[{"question_key":"q4_1","prompt":"Do AI decision processes include human review for high-impact outcomes, where the AI output materially affects an individual's rights, access to services, or financial position?","hint":null,"question_kind":"single","display_order":10,"options":[{"label":"Yes: human review is mandatory for all high-impact outcomes, with documented protocols","score":3,"uncertainty":false},{"label":"Yes: conditionally, based on a defined risk threshold","score":2,"uncertainty":false},{"label":"Rarely: review occurs informally but is not systematic","score":1,"uncertainty":false},{"label":"No: AI outputs are acted upon without human review","score":0,"uncertainty":false}],"is_required":true},{"question_key":"q4_2","prompt":"Are override protocols formally documented for circumstances where a human reviewer disagrees with or wishes to countermand an AI-driven outcome?","hint":null,"question_kind":"single","display_order":20,"options":[{"label":"Yes: formally documented, with records of overrides maintained","score":3,"uncertainty":false},{"label":"Understood informally but not documented","score":1,"uncertainty":false},{"label":"Planned but not yet in place","score":1,"uncertainty":false},{"label":"No","score":0,"uncertainty":false}],"is_required":true},{"question_key":"q4_3","prompt":"Do staff responsible for reviewing AI-assisted decisions receive adequate, documented training, covering both the system's capabilities and its known limitations?","hint":null,"question_kind":"single","display_order":30,"options":[{"label":"Yes: mandatory training with completion records and periodic refresh","score":3,"uncertainty":false},{"label":"Partially: some training exists but inconsistent or undocumented","score":1,"uncertainty":false},{"label":"No formal training in place","score":0,"uncertainty":false}],"is_required":true},{"question_key":"q4_4","prompt":"Are escalation pathways defined and documented for AI-assisted decisions that require additional scrutiny, challenge, or senior review?","hint":null,"question_kind":"single","display_order":40,"options":[{"label":"Yes: clearly documented with named escalation contacts and timescales","score":3,"uncertainty":false},{"label":"Informal pathways are understood but not documented","score":1,"uncertainty":false},{"label":"No escalation pathways defined","score":0,"uncertainty":false}],"is_required":true}]},{"section_key":"s5","title":"Explainability & Transparency","description":"Assessing whether AI-assisted decisions are explainable, traceable, and defensible.","display_order":50,"questions":[{"question_key":"q5_1","prompt":"Can your organisation provide a clear, meaningful explanation for AI-assisted decisions when required, by an individual, a regulator, or in a legal context?","hint":null,"question_kind":"single","display_order":10,"options":[{"label":"Yes: consistently, with a documented explanation methodology","score":3,"uncertainty":false},{"label":"In most cases: explanations possible but not always documented","score":2,"uncertainty":false},{"label":"Only in limited circumstances: depends on system and context","score":1,"uncertainty":false},{"label":"No: explanations cannot be produced","score":0,"uncertainty":false}],"is_required":true},{"question_key":"q5_2","prompt":"Do you maintain logs of AI input features, decision outputs, and confidence or probability scores where applicable?","hint":null,"question_kind":"single","display_order":20,"options":[{"label":"Yes: detailed logs retained for a defined period, accessible for audit","score":3,"uncertainty":false},{"label":"Partially: some logging exists but incomplete or inconsistently retained","score":1,"uncertainty":false},{"label":"No logging in place","score":0,"uncertainty":false}],"is_required":true},{"question_key":"q5_3","prompt":"Are decision logic, model versions, and model change history recorded and accessible for internal audit and regulatory examination?","hint":null,"question_kind":"single","display_order":30,"options":[{"label":"Yes: all versions documented with change rationale, accessible on request","score":3,"uncertainty":false},{"label":"Partially: some version information recorded but not comprehensively","score":1,"uncertainty":false},{"label":"No: model versioning is not tracked","score":0,"uncertainty":false}],"is_required":true},{"question_key":"q5_4","prompt":"Can a specific AI-assisted decision be traced back to its source inputs, the model version that produced it, and the logic applied: for any decision made in the past 12 months?","hint":null,"question_kind":"single","display_order":40,"options":[{"label":"Always: full traceability across all AI-assisted decisions","score":3,"uncertainty":false},{"label":"In most cases: some decisions can be traced but not all","score":2,"uncertainty":false},{"label":"Rarely: traceability possible only in limited circumstances","score":1,"uncertainty":false},{"label":"Never: decisions cannot be reconstructed","score":0,"uncertainty":false}],"is_required":true},{"question_key":"q5_5","prompt":"Are AI systems tested for bias, fairness, or discriminatory outputs, before deployment and on an ongoing basis, with results documented?","hint":null,"question_kind":"single","display_order":50,"options":[{"label":"Yes: formal testing methodology, documented results, periodic re-testing schedule","score":3,"uncertainty":false},{"label":"Some testing conducted but not systematic or documented","score":1,"uncertainty":false},{"label":"No formal testing for bias or fairness","score":0,"uncertainty":false},{"label":"Not applicable: our AI systems do not produce outputs affecting individuals","score":1,"uncertainty":false}],"is_required":true}]},{"section_key":"s6","title":"Compliance & Legal Alignment","description":"Confirming awareness and active alignment with UK and EU legal obligations.","display_order":60,"questions":[{"question_key":"q6_1","prompt":"Has your organisation conducted a formal Data Protection Impact Assessment (DPIA) for AI systems that process personal data, and has it been reviewed within the last 12 months?","hint":null,"question_kind":"single","display_order":10,"options":[{"label":"Yes: completed, reviewed within 12 months, and documented","score":3,"uncertainty":false},{"label":"Yes: completed but not reviewed recently (more than 12 months ago)","score":2,"uncertainty":false},{"label":"Planned but not yet completed","score":1,"uncertainty":false},{"label":"No DPIA has been conducted","score":0,"uncertainty":false},{"label":"Not required: our AI systems do not process personal data","score":2,"uncertainty":false}],"is_required":true},{"question_key":"q6_2","prompt":"Are individuals informed: at the point of interaction or decision: when automated or AI-assisted processes are used in ways that materially affect them?","hint":null,"question_kind":"single","display_order":20,"options":[{"label":"Yes: always, with documented transparency notices","score":3,"uncertainty":false},{"label":"Partially: in some contexts but not comprehensively","score":1,"uncertainty":false},{"label":"No: individuals are not informed","score":0,"uncertainty":false}],"is_required":true},{"question_key":"q6_3","prompt":"Is there a documented process allowing individuals to request human review of, or formally challenge, an AI-assisted decision that affects them?","hint":null,"question_kind":"single","display_order":30,"options":[{"label":"Yes: formally documented, with defined timescales and named responsible function","score":3,"uncertainty":false},{"label":"Limited process exists: requests can be made but the process is not documented","score":1,"uncertainty":false},{"label":"No mechanism exists","score":0,"uncertainty":false}],"is_required":true},{"question_key":"q6_4","prompt":"Has your organisation assessed which of its AI systems fall within the scope of the EU AI Act, including any that may qualify as high-risk under Annex III?","hint":null,"question_kind":"single","display_order":40,"options":[{"label":"Yes: formal scope assessment conducted, documented, and kept under review","score":3,"uncertainty":false},{"label":"Partially: some systems assessed but not comprehensively","score":2,"uncertainty":false},{"label":"No: EU AI Act scope has not been formally assessed","score":0,"uncertainty":false},{"label":"Unsure whether the EU AI Act applies to our organisation","score":0,"uncertainty":true}],"is_required":true},{"question_key":"q6_5","prompt":"Are individuals able to exercise their data rights in relation to AI-assisted decisions, including the right to explanation, objection, and erasure?","hint":null,"question_kind":"single","display_order":50,"options":[{"label":"Yes: all applicable rights supported with documented processes and response timescales","score":3,"uncertainty":false},{"label":"Partially: some rights accommodated but not all, or processes are informal","score":1,"uncertainty":false},{"label":"No: rights requests relating to AI decisions are not formally handled","score":0,"uncertainty":false}],"is_required":true}]},{"section_key":"s7","title":"Operational Controls & Resilience","description":"Assessing the robustness of risk controls, third-party management, and operational resilience around AI systems.","display_order":70,"questions":[{"question_key":"q7_1","prompt":"Are AI systems included in your organisation's formal risk and control self-assessment (RCSA) or equivalent risk register?","hint":null,"question_kind":"single","display_order":10,"options":[{"label":"Yes: all AI systems are explicitly included in the risk framework","score":3,"uncertainty":false},{"label":"Partially: some AI systems are included but not comprehensively","score":2,"uncertainty":false},{"label":"No: AI is not included in formal risk assessments","score":0,"uncertainty":false}],"is_required":true},{"question_key":"q7_2","prompt":"Do third-party AI providers and AI-enabled services undergo structured due diligence, covering data handling, contractual obligations, and ongoing performance review?","hint":null,"question_kind":"single","display_order":20,"options":[{"label":"Yes: formal due diligence with documented outputs and contractual controls","score":3,"uncertainty":false},{"label":"Partially: some review occurs but not systematically","score":2,"uncertainty":false},{"label":"No structured review of third-party AI providers","score":0,"uncertainty":false},{"label":"We do not use third-party AI providers","score":3,"uncertainty":false}],"is_required":true},{"question_key":"q7_3","prompt":"Are cybersecurity and adversarial vulnerabilities assessed for AI systems?","hint":"e.g. prompt injection, model manipulation, data poisoning: these are AI-specific and not captured by standard cybersecurity assessments","question_kind":"single","display_order":30,"options":[{"label":"Yes: AI-specific security testing formally conducted","score":3,"uncertainty":false},{"label":"Partially: some assessment conducted but not AI-specific","score":2,"uncertainty":false},{"label":"No: standard cybersecurity applies but AI-specific risks not assessed","score":1,"uncertainty":false},{"label":"Not currently applicable to our scale or AI use","score":1,"uncertainty":false}],"is_required":true},{"question_key":"q7_4","prompt":"Do you monitor AI model performance on an ongoing basis, tracking accuracy, drift, and degradation, with defined thresholds that trigger review?","hint":null,"question_kind":"single","display_order":40,"options":[{"label":"Yes: automated monitoring with defined thresholds and documented review process","score":3,"uncertainty":false},{"label":"Yes: manual monitoring, periodically reviewed","score":2,"uncertainty":false},{"label":"Partially: some monitoring but without defined thresholds or process","score":1,"uncertainty":false},{"label":"No monitoring in place","score":0,"uncertainty":false}],"is_required":true},{"question_key":"q7_5","prompt":"Does your organisation have a defined incident response process specifically for AI system failures, harmful outputs, or unexpected behaviour?","hint":null,"question_kind":"single","display_order":50,"options":[{"label":"Yes: formally documented, tested, and includes AI-specific scenarios","score":3,"uncertainty":false},{"label":"Yes: general incident response applies but AI-specific scenarios not addressed","score":1,"uncertainty":false},{"label":"No formal incident response process for AI failures","score":0,"uncertainty":false}],"is_required":true}]}]$json$::jsonb;
  sec jsonb;
  q jsonb;
begin
  if exists (select 1 from public.diagnostic_questions limit 1) then
    return;
  end if;
  for sec in select * from jsonb_array_elements(seed) loop
    insert into public.diagnostic_sections (section_key, title, description, display_order)
    values (
      sec->>'section_key',
      sec->>'title',
      sec->>'description',
      coalesce((sec->>'display_order')::int, 0)
    )
    on conflict (section_key) do update set
      title = excluded.title,
      description = excluded.description,
      display_order = excluded.display_order,
      is_active = true,
      updated_at = now();
    for q in select * from jsonb_array_elements(sec->'questions') loop
      insert into public.diagnostic_questions (
        section_key, question_key, prompt, hint, question_kind, is_required, display_order, options
      )
      values (
        sec->>'section_key',
        q->>'question_key',
        q->>'prompt',
        nullif(q->>'hint',''),
        case when q->>'question_kind' = 'multi' then 'multi' else 'single' end,
        coalesce((q->>'is_required')::boolean, true),
        coalesce((q->>'display_order')::int, 0),
        coalesce(q->'options', '[]'::jsonb)
      )
      on conflict (question_key) do update set
        section_key = excluded.section_key,
        prompt = excluded.prompt,
        hint = excluded.hint,
        question_kind = excluded.question_kind,
        is_required = excluded.is_required,
        display_order = excluded.display_order,
        options = excluded.options,
        is_active = true,
        updated_at = now();
    end loop;
  end loop;
end
$do$;
